import{M as e,O as t,d as n,h as r,p as i}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as a}from"./app-C2_RPK_4.js";var o=JSON.parse(`{"path":"/Linux/07_Nginx/05_SSL_TLS%E4%B8%8EHTTPS/03_HTTPS%E5%AE%89%E5%85%A8%E5%8A%A0%E5%9B%BA.html","title":"HTTPS 安全加固","lang":"zh-CN","frontmatter":{"title":"HTTPS 安全加固","icon":"fa6-solid:shield-halved","order":3,"category":["Linux","Nginx"],"tag":["HTTPS","HSTS","CSP","安全头部","SSL Labs"]},"git":{"createdTime":1780631738000,"updatedTime":1780631738000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":18.7,"words":5609},"filePathRelative":"Linux/07_Nginx/05_SSL_TLS与HTTPS/03_HTTPS安全加固.md"}`),s={name:`03_HTTPS安全加固.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<h1 id="https-安全加固" tabindex="-1"><a class="header-anchor" href="#https-安全加固"><span>HTTPS 安全加固</span></a></h1><h2 id="安全加固概述" tabindex="-1"><a class="header-anchor" href="#安全加固概述"><span>安全加固概述</span></a></h2><p>部署 HTTPS 只是安全通信的第一步。默认配置往往存在多种安全隐患：协议降级攻击、弱密码套件、缺少安全响应头等。HTTPS 安全加固的目标是确保 TLS 连接的每个环节都达到最高安全标准。</p><p>安全加固的核心原则：</p><ul><li><strong>纵深防御</strong>：不依赖单一安全机制</li><li><strong>最小暴露</strong>：禁用一切不必要的特性</li><li><strong>主动防护</strong>：通过 HSTS 等机制防止降级</li><li><strong>持续监测</strong>：定期进行安全评估</li></ul>`,5),r(d,{code:``}),o[1]||=i(`<hr><h2 id="hsts-http-strict-transport-security" tabindex="-1"><a class="header-anchor" href="#hsts-http-strict-transport-security"><span>HSTS（HTTP Strict Transport Security）</span></a></h2><h3 id="hsts-原理" tabindex="-1"><a class="header-anchor" href="#hsts-原理"><span>HSTS 原理</span></a></h3><p>HSTS 是一种安全策略机制，告诉浏览器只能通过 HTTPS 访问当前网站，有效防止协议降级攻击和 Cookie 劫持：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>无 HSTS 的攻击场景：</span></span>
<span class="line"><span>1. 用户输入 example.com（浏览器默认使用 HTTP）</span></span>
<span class="line"><span>2. 攻击者截获 HTTP 请求（中间人攻击）</span></span>
<span class="line"><span>3. 攻击者可以：</span></span>
<span class="line"><span>   a. 窃取会话 Cookie</span></span>
<span class="line"><span>   b. 注入恶意内容</span></span>
<span class="line"><span>   c. 修改重定向目标</span></span>
<span class="line"><span></span></span>
<span class="line"><span>有 HSTS 的防护：</span></span>
<span class="line"><span>1. 首次访问后，浏览器缓存 HSTS 策略</span></span>
<span class="line"><span>2. 后续所有请求自动升级为 HTTPS</span></span>
<span class="line"><span>3. 即使用户输入 http://，浏览器也会内部转换为 https://</span></span>
<span class="line"><span>4. 中间人无法降级连接</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="hsts-响应头格式" tabindex="-1"><a class="header-anchor" href="#hsts-响应头格式"><span>HSTS 响应头格式</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>Strict-Transport-Security: max-age=&lt;expire-time&gt;[; includeSubDomains][; preload]</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>参数说明：</p><table><thead><tr><th>参数</th><th>说明</th><th>推荐</th></tr></thead><tbody><tr><td><code>max-age</code></td><td>策略有效期（秒）</td><td>至少 31536000（1 年）</td></tr><tr><td><code>includeSubDomains</code></td><td>策略应用于所有子域名</td><td>推荐启用</td></tr><tr><td><code>preload</code></td><td>申请加入浏览器预加载列表</td><td>推荐启用</td></tr></tbody></table><h3 id="nginx-hsts-配置" tabindex="-1"><a class="header-anchor" href="#nginx-hsts-配置"><span>Nginx HSTS 配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Strict-Transport-Security</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">    /etc/nginx/ssl/example.com-fullchain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 基础 HSTS（6 个月）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # add_header Strict-Transport-Security &quot;max-age=15768000&quot; always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 推荐 HSTS（1 年 + 子域名）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # add_header Strict-Transport-Security &quot;max-age=31536000; includeSubDomains&quot; always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 最强 HSTS（1 年 + 子域名 + preload）</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Strict-Transport-Security </span><span style="color:#98C379;">&quot;max-age=63072000; includeSubDomains; preload&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">        root </span><span style="color:#ABB2BF;">/var/www/html;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">HSTS 的风险</p><ul><li><code>max-age</code> 设置过大时，如果 HTTPS 服务出现故障，用户在有效期内将无法访问网站</li><li><code>includeSubDomains</code> 会影响所有子域名，如果某个子域名不支持 HTTPS，将无法访问</li><li><code>preload</code> 几乎不可逆，需要从浏览器预加载列表中手动移除</li></ul><p><strong>推荐的分阶段部署策略</strong>：</p><ol><li>先设置 <code>max-age=300</code>（5 分钟）测试</li><li>确认无问题后设置为 <code>max-age=86400</code>（1 天）</li><li>再次确认后设置为 <code>max-age=31536000</code>（1 年）</li><li>最后添加 <code>includeSubDomains</code> 和 <code>preload</code></li></ol></div><h3 id="hsts-preload-列表" tabindex="-1"><a class="header-anchor" href="#hsts-preload-列表"><span>HSTS Preload 列表</span></a></h3><p>HSTS Preload 是一个由 Chrome 维护的硬编码 HTTPS 站点列表，内置于所有主流浏览器中。加入 Preload 列表的站点即使从未被访问过，浏览器也会强制使用 HTTPS。</p><p>申请 Preload 列表的条件：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 必须有有效的 HTTPS 证书</span></span>
<span class="line"><span>2. HTTP 必须重定向到 HTTPS（同一主机）</span></span>
<span class="line"><span>3. 所有子域名必须支持 HTTPS（如果设置了 includeSubDomains）</span></span>
<span class="line"><span>4. HSTS 头必须包含：</span></span>
<span class="line"><span>   - max-age &gt;= 31536000（1 年）</span></span>
<span class="line"><span>   - includeSubDomains</span></span>
<span class="line"><span>   - preload</span></span>
<span class="line"><span>5. 重定向后的 HTTPS 站点也必须有 HSTS 头</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>申请流程：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>1. 确保网站满足上述条件</span></span>
<span class="line"><span>2. 访问 https://hstspreload.org/</span></span>
<span class="line"><span>3. 提交域名</span></span>
<span class="line"><span>4. 等待浏览器更新（通常需要数周到数月）</span></span>
<span class="line"><span>5. 域名被硬编码到浏览器源码中</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">Preload 几乎不可逆</p><p>加入 Preload 列表后，移除需要：</p><ol><li>修改 HSTS 头（移除 preload）</li><li>在 <a href="http://hstspreload.org" target="_blank" rel="noopener noreferrer">hstspreload.org</a> 提交移除请求</li><li>等待浏览器版本更新<br> 整个过程可能需要数月。在提交前务必确认所有子域名都支持 HTTPS。</li></ol></div><hr><h2 id="csp-content-security-policy" tabindex="-1"><a class="header-anchor" href="#csp-content-security-policy"><span>CSP（Content-Security-Policy）</span></a></h2><h3 id="csp-原理" tabindex="-1"><a class="header-anchor" href="#csp-原理"><span>CSP 原理</span></a></h3><p>CSP 是一种声明式安全机制，允许网站管理员控制浏览器可以加载哪些资源，有效防御 XSS（跨站脚本攻击）和数据注入攻击：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>没有 CSP 时：</span></span>
<span class="line"><span>- 浏览器加载所有来源的脚本</span></span>
<span class="line"><span>- XSS 注入的恶意脚本可以执行</span></span>
<span class="line"><span>- 内联脚本、eval() 等都可以运行</span></span>
<span class="line"><span></span></span>
<span class="line"><span>有 CSP 时：</span></span>
<span class="line"><span>- 浏览器仅加载白名单来源的资源</span></span>
<span class="line"><span>- 恶意脚本被阻止执行</span></span>
<span class="line"><span>- 可禁用内联脚本和 eval()</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="csp-指令详解" tabindex="-1"><a class="header-anchor" href="#csp-指令详解"><span>CSP 指令详解</span></a></h3><table><thead><tr><th>指令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>default-src</code></td><td>默认资源策略</td><td><code>&#39;self&#39;</code></td></tr><tr><td><code>script-src</code></td><td>JavaScript 来源</td><td><code>&#39;self&#39; &#39;unsafe-inline&#39;</code></td></tr><tr><td><code>style-src</code></td><td>CSS 来源</td><td><code>&#39;self&#39; &#39;unsafe-inline&#39;</code></td></tr><tr><td><code>img-src</code></td><td>图片来源</td><td><code>&#39;self&#39; data: https:</code></td></tr><tr><td><code>font-src</code></td><td>字体来源</td><td><code>&#39;self&#39; https://fonts.gstatic.com</code></td></tr><tr><td><code>connect-src</code></td><td>XHR/Fetch/WebSocket 来源</td><td><code>&#39;self&#39; https://api.example.com</code></td></tr><tr><td><code>media-src</code></td><td>音视频来源</td><td><code>&#39;self&#39;</code></td></tr><tr><td><code>frame-src</code></td><td>iframe 来源</td><td><code>&#39;self&#39;</code></td></tr><tr><td><code>object-src</code></td><td>Flash/插件来源</td><td><code>&#39;none&#39;</code></td></tr><tr><td><code>base-uri</code></td><td><code>&lt;base&gt;</code> 标签限制</td><td><code>&#39;self&#39;</code></td></tr><tr><td><code>form-action</code></td><td>表单提交目标</td><td><code>&#39;self&#39;</code></td></tr><tr><td><code>frame-ancestors</code></td><td>嵌入此页的来源</td><td><code>&#39;none&#39;</code>（替代 X-Frame-Options）</td></tr><tr><td><code>upgrade-insecure-requests</code></td><td>自动升级 HTTP 为 HTTPS</td><td>（无值）</td></tr><tr><td><code>block-all-mixed-content</code></td><td>阻止混合内容</td><td>（无值）</td></tr></tbody></table><h3 id="csp-源值说明" tabindex="-1"><a class="header-anchor" href="#csp-源值说明"><span>CSP 源值说明</span></a></h3><table><thead><tr><th>源值</th><th>说明</th></tr></thead><tbody><tr><td><code>&#39;self&#39;</code></td><td>同源（相同协议、域名、端口）</td></tr><tr><td><code>&#39;none&#39;</code></td><td>不允许任何来源</td></tr><tr><td><code>&#39;unsafe-inline&#39;</code></td><td>允许内联脚本/样式（降低安全性）</td></tr><tr><td><code>&#39;unsafe-eval&#39;</code></td><td>允许 eval()、new Function() 等（降低安全性）</td></tr><tr><td><code>&#39;nonce-&lt;base64&gt;&#39;</code></td><td>允许匹配 nonce 的内联脚本</td></tr><tr><td><code>&#39;sha256-&lt;hash&gt;&#39;</code></td><td>允许匹配哈希的内联脚本</td></tr><tr><td><code>https:</code></td><td>允许任何 HTTPS 来源</td></tr><tr><td><code>*.example.com</code></td><td>允许 <a href="http://example.com" target="_blank" rel="noopener noreferrer">example.com</a> 的所有子域名</td></tr></tbody></table><h3 id="nginx-csp-配置" tabindex="-1"><a class="header-anchor" href="#nginx-csp-配置"><span>Nginx CSP 配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://developer.mozilla.org/en-US/docs/Web/HTTP/CSP</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 严格的 CSP（推荐）</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Content-Security-Policy </span><span style="color:#98C379;">&quot;default-src &#39;self&#39;; script-src &#39;self&#39;; style-src &#39;self&#39; &#39;unsafe-inline&#39;; img-src &#39;self&#39; data: https:; font-src &#39;self&#39; https://fonts.gstatic.com; connect-src &#39;self&#39; https://api.example.com; frame-ancestors &#39;none&#39;; base-uri &#39;self&#39;; form-action &#39;self&#39;; upgrade-insecure-requests&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 使用 nonce 的 CSP（更安全）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 需要在后端为每个页面生成唯一的 nonce 值</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # add_header Content-Security-Policy &quot;default-src &#39;self&#39;; script-src &#39;self&#39; &#39;nonce-$request_id&#39;; style-src &#39;self&#39; &#39;unsafe-inline&#39;; ...&quot; always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 仅报告模式（部署 CSP 前先观察）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # add_header Content-Security-Policy-Report-Only &quot;default-src &#39;self&#39;; ...&quot; always;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="csp-分阶段部署策略" tabindex="-1"><a class="header-anchor" href="#csp-分阶段部署策略"><span>CSP 分阶段部署策略</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 阶段 1：仅报告模式（不阻止任何内容）</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">Content-Security-Policy-Report-Only </span><span style="color:#98C379;">&quot;default-src &#39;self&#39;; script-src &#39;self&#39;; style-src &#39;self&#39; &#39;unsafe-inline&#39;; img-src &#39;self&#39; data: https:; report-uri /csp-report&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 配置 CSP 报告接收端点</span></span>
<span class="line"><span style="color:#C678DD;">location</span><span style="color:#ABB2BF;"> /csp-report {</span></span>
<span class="line"><span style="color:#C678DD;">    access_log </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    proxy_pass </span><span style="color:#ABB2BF;">http://csp_collector;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 或者记录到文件</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # return 204;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 阶段 2：宽松模式（允许必要的不安全来源）</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">Content-Security-Policy </span><span style="color:#98C379;">&quot;default-src &#39;self&#39;; script-src &#39;self&#39; &#39;unsafe-inline&#39; &#39;unsafe-eval&#39;; style-src &#39;self&#39; &#39;unsafe-inline&#39;; img-src &#39;self&#39; data: https:; frame-ancestors &#39;self&#39;&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 阶段 3：严格模式（移除 unsafe-inline/unsafe-eval）</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">Content-Security-Policy </span><span style="color:#98C379;">&quot;default-src &#39;self&#39;; script-src &#39;self&#39;; style-src &#39;self&#39; &#39;unsafe-inline&#39;; img-src &#39;self&#39; data: https:; frame-ancestors &#39;none&#39;; upgrade-insecure-requests&quot;</span><span style="color:#ABB2BF;"> always;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">CSP 与 Nginx 变量</p><p>Nginx 的 <code>$request_id</code> 变量可以作为 CSP nonce 使用。但注意，<code>add_header</code> 中使用变量时，Nginx 会为每个请求生成新值，这可以满足 nonce 的唯一性要求。但需要后端应用在 HTML 中使用相同的 nonce 值。</p></div><hr><h2 id="安全响应头" tabindex="-1"><a class="header-anchor" href="#安全响应头"><span>安全响应头</span></a></h2><h3 id="x-frame-options" tabindex="-1"><a class="header-anchor" href="#x-frame-options"><span>X-Frame-Options</span></a></h3><p>防止页面被嵌入 iframe，防御点击劫持（Clickjacking）攻击：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 语法：DENY | SAMEORIGIN | ALLOW-FROM uri</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 注意：ALLOW-FROM 已被多数浏览器弃用，使用 CSP frame-ancestors 替代</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 完全禁止嵌入（推荐）</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">X-Frame-Options </span><span style="color:#98C379;">&quot;DENY&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 仅允许同源嵌入</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">X-Frame-Options </span><span style="color:#98C379;">&quot;SAMEORIGIN&quot;</span><span style="color:#ABB2BF;"> always;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>值</th><th>说明</th></tr></thead><tbody><tr><td><code>DENY</code></td><td>完全禁止被嵌入 iframe</td></tr><tr><td><code>SAMEORIGIN</code></td><td>仅允许同源页面嵌入</td></tr></tbody></table><h3 id="x-content-type-options" tabindex="-1"><a class="header-anchor" href="#x-content-type-options"><span>X-Content-Type-Options</span></a></h3><p>防止浏览器 MIME 类型嗅探（MIME Sniffing），减少 XSS 攻击面：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 唯一有效值：nosniff</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">X-Content-Type-Options </span><span style="color:#98C379;">&quot;nosniff&quot;</span><span style="color:#ABB2BF;"> always;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>攻击场景（无此头部）：</span></span>
<span class="line"><span>1. 攻击者上传一个文件，扩展名为 .jpg，但内容是 JavaScript</span></span>
<span class="line"><span>2. 服务器返回 Content-Type: image/jpeg</span></span>
<span class="line"><span>3. 浏览器嗅探到内容是 JavaScript，以脚本方式执行</span></span>
<span class="line"><span>4. XSS 攻击成功</span></span>
<span class="line"><span></span></span>
<span class="line"><span>防护（有此头部）：</span></span>
<span class="line"><span>1. 服务器返回 Content-Type: image/jpeg + X-Content-Type-Options: nosniff</span></span>
<span class="line"><span>2. 浏览器严格遵循 Content-Type，不嗅探</span></span>
<span class="line"><span>3. JavaScript 内容不会被执行</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="x-xss-protection" tabindex="-1"><a class="header-anchor" href="#x-xss-protection"><span>X-XSS-Protection</span></a></h3><p>控制浏览器内置的 XSS 过滤器（仅 Chrome/IE/Safari 支持，已被 CSP 替代）：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 禁用 XSS 过滤器（推荐，由 CSP 接管）</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">X-XSS-Protection </span><span style="color:#98C379;">&quot;0&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 启用 XSS 过滤器</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># add_header X-XSS-Protection &quot;1&quot; always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 启用 XSS 过滤器 + 阻止渲染</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># add_header X-XSS-Protection &quot;1; mode=block&quot; always;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">X-XSS-Protection 的安全问题</p><p>现代安全实践建议设置 <code>X-XSS-Protection: 0</code>，因为：</p><ul><li>XSS 过滤器本身存在漏洞，可能被利用来执行攻击</li><li>正确配置的 CSP 是更可靠的 XSS 防御手段</li><li>Firefox 从未支持此头部</li><li>Chrome 78+ 已移除 XSS Auditor</li></ul></div><h3 id="referrer-policy" tabindex="-1"><a class="header-anchor" href="#referrer-policy"><span>Referrer-Policy</span></a></h3><p>控制 Referer 头部中携带的来源信息，保护用户隐私：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 推荐配置：HTTPS→HTTPS 仅发送来源域名</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">Referrer-Policy </span><span style="color:#98C379;">&quot;strict-origin-when-cross-origin&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 最严格：不发送 Referer</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># add_header Referrer-Policy &quot;no-referrer&quot; always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 同源发送完整 URL，跨源仅发送域名</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># add_header Referrer-Policy &quot;origin-when-cross-origin&quot; always;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>值</th><th>同源请求</th><th>跨源请求</th><th>HTTPS→HTTP</th></tr></thead><tbody><tr><td><code>no-referrer</code></td><td>不发送</td><td>不发送</td><td>不发送</td></tr><tr><td><code>no-referrer-when-downgrade</code></td><td>完整 URL</td><td>完整 URL</td><td>不发送</td></tr><tr><td><code>origin</code></td><td>域名</td><td>域名</td><td>域名</td></tr><tr><td><code>origin-when-cross-origin</code></td><td>完整 URL</td><td>域名</td><td>域名</td></tr><tr><td><code>strict-origin</code></td><td>域名</td><td>域名</td><td>不发送</td></tr><tr><td><code>strict-origin-when-cross-origin</code></td><td>完整 URL</td><td>域名</td><td>不发送</td></tr><tr><td><code>same-origin</code></td><td>完整 URL</td><td>不发送</td><td>不发送</td></tr></tbody></table><h3 id="permissions-policy" tabindex="-1"><a class="header-anchor" href="#permissions-policy"><span>Permissions-Policy</span></a></h3><p>控制浏览器 API 的使用权限（原 Feature-Policy）：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 禁用不需要的浏览器 API</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">Permissions-Policy </span><span style="color:#98C379;">&quot;camera=(), microphone=(), geolocation=(), payment=(), usb=(), magnetometer=(), gyroscope=(), accelerometer=()&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 仅允许同源使用</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># add_header Permissions-Policy &quot;camera=(self), microphone=(self), geolocation=(self)&quot; always;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="cross-origin-安全头" tabindex="-1"><a class="header-anchor" href="#cross-origin-安全头"><span>Cross-Origin 安全头</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># Cross-Origin-Opener-Policy (COOP)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 防止跨源窗口访问</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">Cross-Origin-Opener-Policy </span><span style="color:#98C379;">&quot;same-origin&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Cross-Origin-Embedder-Policy (COEP)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 控制跨源资源加载</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">Cross-Origin-Embedder-Policy </span><span style="color:#98C379;">&quot;require-corp&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Cross-Origin-Resource-Policy (CORP)</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 控制跨源资源访问</span></span>
<span class="line"><span style="color:#C678DD;">add_header </span><span style="color:#ABB2BF;">Cross-Origin-Resource-Policy </span><span style="color:#98C379;">&quot;same-origin&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Access-Control-Allow-Origin（CORS）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 仅在需要跨域时配置</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># add_header Access-Control-Allow-Origin &quot;https://trusted-site.com&quot; always;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="完整安全头部配置" tabindex="-1"><a class="header-anchor" href="#完整安全头部配置"><span>完整安全头部配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">    /etc/nginx/ssl/example.com-fullchain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== HSTS =====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Strict-Transport-Security </span><span style="color:#98C379;">&quot;max-age=63072000; includeSubDomains; preload&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== CSP =====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Content-Security-Policy </span><span style="color:#98C379;">&quot;default-src &#39;self&#39;; script-src &#39;self&#39;; style-src &#39;self&#39; &#39;unsafe-inline&#39;; img-src &#39;self&#39; data: https:; font-src &#39;self&#39; https://fonts.gstatic.com; connect-src &#39;self&#39;; frame-ancestors &#39;none&#39;; base-uri &#39;self&#39;; form-action &#39;self&#39;; upgrade-insecure-requests&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 点击劫持防护 =====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">X-Frame-Options </span><span style="color:#98C379;">&quot;DENY&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== MIME 嗅探防护 =====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">X-Content-Type-Options </span><span style="color:#98C379;">&quot;nosniff&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== XSS 防护 =====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">X-XSS-Protection </span><span style="color:#98C379;">&quot;0&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== Referer 策略 =====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Referrer-Policy </span><span style="color:#98C379;">&quot;strict-origin-when-cross-origin&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 权限策略 =====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Permissions-Policy </span><span style="color:#98C379;">&quot;camera=(), microphone=(), geolocation=()&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 跨源策略 =====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cross-Origin-Opener-Policy </span><span style="color:#98C379;">&quot;same-origin&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cross-Origin-Embedder-Policy </span><span style="color:#98C379;">&quot;require-corp&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Cross-Origin-Resource-Policy </span><span style="color:#98C379;">&quot;same-origin&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">        root </span><span style="color:#ABB2BF;">/var/www/html;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="密码套件安全配置" tabindex="-1"><a class="header-anchor" href="#密码套件安全配置"><span>密码套件安全配置</span></a></h2><h3 id="安全等级划分" tabindex="-1"><a class="header-anchor" href="#安全等级划分"><span>安全等级划分</span></a></h3>`,61),r(d,{code:``}),o[2]||=i(`<h3 id="推荐密码套件配置" tabindex="-1"><a class="header-anchor" href="#推荐密码套件配置"><span>推荐密码套件配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_ciphers</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ===== Mozilla Modern 配置 =====</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 仅允许 AEAD + ECDHE，最高安全等级</span></span>
<span class="line"><span style="color:#C678DD;">ssl_ciphers </span><span style="color:#98C379;">&#39;ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ===== Mozilla Intermediate 配置 =====</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 额外允许 DHE，兼容性更好</span></span>
<span class="line"><span style="color:#C678DD;">ssl_ciphers </span><span style="color:#98C379;">&#39;ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ===== 使用排除法的配置 =====</span></span>
<span class="line"><span style="color:#C678DD;">ssl_ciphers </span><span style="color:#98C379;">&#39;ECDHE+AESGCM:ECDHE+CHACHA20:DHE+AESGCM:DHE+CHACHA20:!aNULL:!MD5:!DSS:!AESCCM:!3DES&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="密码套件安全审计" tabindex="-1"><a class="header-anchor" href="#密码套件安全审计"><span>密码套件安全审计</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 列出当前配置的所有密码套件及安全等级</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> ciphers</span><span style="color:#D19A66;"> -v</span><span style="color:#98C379;"> &#39;ECDHE+AESGCM:ECDHE+CHACHA20:DHE+AESGCM&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">  awk</span><span style="color:#98C379;"> &#39;{print $1, $2}&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 测试连接使用的密码套件</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> | </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">  grep</span><span style="color:#98C379;"> &quot;Cipher    :&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 nmap 扫描所有支持的密码套件</span></span>
<span class="line"><span style="color:#61AFEF;">nmap</span><span style="color:#D19A66;"> --script</span><span style="color:#98C379;"> ssl-enum-ciphers</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 testssl.sh 进行全面安全扫描</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://github.com/drwetter/testssl.sh</span></span>
<span class="line"><span style="color:#61AFEF;">./testssl.sh</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> example.com</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="ssl-labs-a-评级配置清单" tabindex="-1"><a class="header-anchor" href="#ssl-labs-a-评级配置清单"><span>SSL Labs A+ 评级配置清单</span></a></h2><h3 id="ssl-labs-评级标准" tabindex="-1"><a class="header-anchor" href="#ssl-labs-评级标准"><span>SSL Labs 评级标准</span></a></h3><p>SSL Labs（Qualys SSL Server Test）对 HTTPS 服务器进行安全评级，评级标准：</p><table><thead><tr><th>评级</th><th>条件</th></tr></thead><tbody><tr><td>A+</td><td>A 级 + HSTS（max-age &gt;= 6 个月）</td></tr><tr><td>A</td><td>协议安全 + 密码套件安全 + 证书有效</td></tr><tr><td>B</td><td>存在轻微安全问题</td></tr><tr><td>C</td><td>存在中等安全问题</td></tr><tr><td>D</td><td>存在严重安全问题</td></tr><tr><td>F</td><td>存在致命安全问题</td></tr><tr><td>T</td><td>证书不受信任</td></tr><tr><td>M</td><td>证书域名不匹配</td></tr></tbody></table><h3 id="a-评级完整配置" tabindex="-1"><a class="header-anchor" href="#a-评级完整配置"><span>A+ 评级完整配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://nginx.org/en/docs/http/ngx_http_ssl_module.html</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://ssl-config.mozilla.org/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#ABB2BF;">[::]:443 ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    http2 </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 证书 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">    /etc/nginx/ssl/example.com-fullchain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 1. 协议版本：仅 TLS 1.2 + 1.3 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_protocols </span><span style="color:#ABB2BF;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 2. 密码套件：仅 AEAD =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_ciphers </span><span style="color:#98C379;">&#39;ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384:DHE-RSA-CHACHA20-POLY1305&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_prefer_server_ciphers </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 3. DH 参数（2048 bit+）=====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_dhparam </span><span style="color:#ABB2BF;">/etc/nginx/ssl/dhparam.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 4. ECDHE 曲线 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_ecdh_curve </span><span style="color:#ABB2BF;">X25519:secp256r1:secp384r1;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 5. Session 恢复 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_cache </span><span style="color:#ABB2BF;">shared:SSL:10m;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_timeout </span><span style="color:#D19A66;">1d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_tickets </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 6. OCSP Stapling =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_stapling </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_stapling_verify </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_trusted_certificate </span><span style="color:#ABB2BF;">/etc/nginx/ssl/chain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    resolver </span><span style="color:#D19A66;">8.8.8.8</span><span style="color:#D19A66;"> 8.8.4.4</span><span style="color:#ABB2BF;"> valid=300s;</span></span>
<span class="line"><span style="color:#C678DD;">    resolver_timeout </span><span style="color:#D19A66;">5s</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 7. HSTS（A+ 必需）=====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Strict-Transport-Security </span><span style="color:#98C379;">&quot;max-age=63072000; includeSubDomains; preload&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 8. 其他安全头 =====</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">X-Frame-Options </span><span style="color:#98C379;">&quot;DENY&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">X-Content-Type-Options </span><span style="color:#98C379;">&quot;nosniff&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">X-XSS-Protection </span><span style="color:#98C379;">&quot;0&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Referrer-Policy </span><span style="color:#98C379;">&quot;strict-origin-when-cross-origin&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== 9. 性能优化 =====</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_buffer_size </span><span style="color:#D19A66;">4k</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">        root </span><span style="color:#ABB2BF;">/var/www/html;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># HTTP → HTTPS 重定向</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#ABB2BF;">[::]:80;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#D19A66;"> 301</span><span style="color:#ABB2BF;"> https://$</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">request_uri</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="ssl-labs-评分检查清单" tabindex="-1"><a class="header-anchor" href="#ssl-labs-评分检查清单"><span>SSL Labs 评分检查清单</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>✅ 证书检查</span></span>
<span class="line"><span>  [ ] 证书有效期正常</span></span>
<span class="line"><span>  [ ] 证书链完整</span></span>
<span class="line"><span>  [ ] 证书域名匹配</span></span>
<span class="line"><span>  [ ] 证书未被吊销</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✅ 协议检查</span></span>
<span class="line"><span>  [ ] 禁用 SSLv3</span></span>
<span class="line"><span>  [ ] 禁用 TLS 1.0</span></span>
<span class="line"><span>  [ ] 禁用 TLS 1.1</span></span>
<span class="line"><span>  [ ] 启用 TLS 1.2</span></span>
<span class="line"><span>  [ ] 启用 TLS 1.3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✅ 密码套件检查</span></span>
<span class="line"><span>  [ ] 无 RC4 密码套件</span></span>
<span class="line"><span>  [ ] 无 3DES 密码套件</span></span>
<span class="line"><span>  [ ] 无 CBC 模式密码套件（或使用 AEAD 替代）</span></span>
<span class="line"><span>  [ ] 支持前向保密</span></span>
<span class="line"><span>  [ ] 无弱密码套件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✅ 安全特性检查</span></span>
<span class="line"><span>  [ ] HSTS 已启用（max-age &gt;= 15768000）</span></span>
<span class="line"><span>  [ ] OCSP Stapling 已启用</span></span>
<span class="line"><span>  [ ] 无协议降级风险</span></span>
<span class="line"><span>  [ ] 无 Beast/Lucky13 漏洞</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✅ 密钥检查</span></span>
<span class="line"><span>  [ ] RSA 密钥 &gt;= 2048 bit</span></span>
<span class="line"><span>  [ ] DH 参数 &gt;= 2048 bit</span></span>
<span class="line"><span>  [ ] ECDHE 曲线使用安全曲线</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="sslv3-tls-1-0-tls-1-1-禁用" tabindex="-1"><a class="header-anchor" href="#sslv3-tls-1-0-tls-1-1-禁用"><span>SSLv3/TLS 1.0/TLS 1.1 禁用</span></a></h2><h3 id="禁用旧协议的原因" tabindex="-1"><a class="header-anchor" href="#禁用旧协议的原因"><span>禁用旧协议的原因</span></a></h3><table><thead><tr><th>协议</th><th>已知漏洞</th><th>CVE</th><th>状态</th></tr></thead><tbody><tr><td>SSLv3</td><td>POODLE</td><td>CVE-2014-3566</td><td>完全不安全</td></tr><tr><td>TLS 1.0</td><td>BEAST</td><td>CVE-2011-3389</td><td>已废弃</td></tr><tr><td>TLS 1.1</td><td>无明显漏洞，但缺乏现代安全特性</td><td>-</td><td>已废弃</td></tr></tbody></table><h3 id="禁用配置" tabindex="-1"><a class="header-anchor" href="#禁用配置"><span>禁用配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/ngx_http_ssl_module.html#ssl_protocols</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 全局配置（在 http 块中）</span></span>
<span class="line"><span style="color:#C678DD;">http</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_protocols </span><span style="color:#ABB2BF;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ...</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 单个 server 配置</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_protocols </span><span style="color:#ABB2BF;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ...</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="验证旧协议已禁用" tabindex="-1"><a class="header-anchor" href="#验证旧协议已禁用"><span>验证旧协议已禁用</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 SSLv3（应连接失败）</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -ssl3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 预期输出：handshake failure</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 TLS 1.0（应连接失败）</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 预期输出：handshake failure</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 TLS 1.1（应连接失败）</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 预期输出：handshake failure</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 TLS 1.2（应连接成功）</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_2</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 预期输出：SSL handshake has read ... bytes</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 测试 TLS 1.3（应连接成功）</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -tls1_3</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 预期输出：SSL handshake has read ... bytes</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="协议降级防护" tabindex="-1"><a class="header-anchor" href="#协议降级防护"><span>协议降级防护</span></a></h3><p>TLS 1.3 内置了降级防护机制（downgrade sentinel），但 TLS 1.2 需要额外配置：</p><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># TLS 1.2 降级防护：防止从 TLS 1.2 降级到 TLS 1.0/1.1</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 仅启用 TLS 1.2+ 即可防止降级</span></span>
<span class="line"><span style="color:#C678DD;">ssl_protocols </span><span style="color:#ABB2BF;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 防止 SSLv3/TLS 1.0 的 Fallback 攻击</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># OpenSSL 1.0.2+ 自带 RFC 7507 防护</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 无需额外 Nginx 配置</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="http-→-https-自动重定向" tabindex="-1"><a class="header-anchor" href="#http-→-https-自动重定向"><span>HTTP → HTTPS 自动重定向</span></a></h2><h3 id="基本重定向" tabindex="-1"><a class="header-anchor" href="#基本重定向"><span>基本重定向</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：https://nginx.org/en/docs/http/configuring_https_servers.html</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#ABB2BF;">[::]:80;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com www.example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 301 永久重定向到 HTTPS</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#D19A66;"> 301</span><span style="color:#ABB2BF;"> https://$</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">request_uri</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="保留请求参数的重定向" tabindex="-1"><a class="header-anchor" href="#保留请求参数的重定向"><span>保留请求参数的重定向</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 保留原始 URI 和查询参数</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#D19A66;"> 301</span><span style="color:#ABB2BF;"> https://$</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">request_uri</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 更复杂的重定向逻辑</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 非标准端口的重定向</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # return 301 https://$host:8443$request_uri;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#D19A66;"> 301</span><span style="color:#ABB2BF;"> https://$</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">request_uri</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 特定路径不重定向（如健康检查）</span></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> /health {</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#D19A66;"> 200</span><span style="color:#98C379;"> &quot;OK&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Content-Type text/plain;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="hsts-重定向的完整方案" tabindex="-1"><a class="header-anchor" href="#hsts-重定向的完整方案"><span>HSTS + 重定向的完整方案</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># HTTP 重定向到 HTTPS</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#ABB2BF;">[::]:80;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com www.example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 301 重定向</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#D19A66;"> 301</span><span style="color:#ABB2BF;"> https://$</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">request_uri</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># HTTPS 主站</span></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#ABB2BF;">[::]:443 ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    http2 </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com www.example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">    /etc/nginx/ssl/example.com-fullchain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # HSTS：确保浏览器后续直接访问 HTTPS</span></span>
<span class="line"><span style="color:#C678DD;">    add_header </span><span style="color:#ABB2BF;">Strict-Transport-Security </span><span style="color:#98C379;">&quot;max-age=63072000; includeSubDomains; preload&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # www → 非 www 重定向（可选）</span></span>
<span class="line"><span style="color:#C678DD;">    if</span><span style="color:#ABB2BF;"> ($</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;"> = </span><span style="color:#98C379;">&#39;www.example.com&#39;</span><span style="color:#ABB2BF;">) {</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#D19A66;"> 301</span><span style="color:#ABB2BF;"> https://example.com$</span><span style="color:#E06C75;">request_uri</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">        root </span><span style="color:#ABB2BF;">/var/www/html;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container important"><p class="hint-container-title">重定向与 HSTS 的配合</p><ul><li>单独的重定向仍可能被中间人攻击（首次 HTTP 请求时）</li><li>HSTS 确保浏览器在 <code>max-age</code> 有效期内直接使用 HTTPS</li><li>两者配合形成完整防护：重定向处理首次访问，HSTS 处理后续访问</li><li>Preload 列表确保从未访问过的用户也受到保护</li></ul></div><hr><h2 id="caa-记录与证书透明度-ct" tabindex="-1"><a class="header-anchor" href="#caa-记录与证书透明度-ct"><span>CAA 记录与证书透明度（CT）</span></a></h2><h3 id="caa-certification-authority-authorization" tabindex="-1"><a class="header-anchor" href="#caa-certification-authority-authorization"><span>CAA（Certification Authority Authorization）</span></a></h3><p>CAA 是一种 DNS 记录，指定哪些 CA 有权为域名签发证书：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span># CAA 记录语法</span></span>
<span class="line"><span>example.com. IN CAA 0 issue &quot;letsencrypt.org&quot;</span></span>
<span class="line"><span>example.com. IN CAA 0 issuewild &quot;;&quot;</span></span>
<span class="line"><span>example.com. IN CAA 0 iodef &quot;mailto:security@example.com&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>标志</th><th>标签</th><th>说明</th></tr></thead><tbody><tr><td>0</td><td><code>issue</code></td><td>允许指定 CA 签发证书</td></tr><tr><td>0</td><td><code>issuewild</code></td><td>允许指定 CA 签发通配符证书</td></tr><tr><td>0</td><td><code>iodef</code></td><td>违规报告发送地址</td></tr><tr><td>128</td><td><code>issue</code></td><td>关键标志，CA 必须理解此记录才能签发</td></tr></tbody></table><h3 id="caa-配置示例" tabindex="-1"><a class="header-anchor" href="#caa-配置示例"><span>CAA 配置示例</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 仅允许 Let&#39;s Encrypt 签发证书</span></span>
<span class="line"><span style="color:#61AFEF;">example.com.</span><span style="color:#98C379;"> IN</span><span style="color:#98C379;"> CAA</span><span style="color:#D19A66;"> 0</span><span style="color:#98C379;"> issue</span><span style="color:#98C379;"> &quot;letsencrypt.org&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">example.com.</span><span style="color:#98C379;"> IN</span><span style="color:#98C379;"> CAA</span><span style="color:#D19A66;"> 0</span><span style="color:#98C379;"> issuewild</span><span style="color:#98C379;"> &quot;;&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">example.com.</span><span style="color:#98C379;"> IN</span><span style="color:#98C379;"> CAA</span><span style="color:#D19A66;"> 0</span><span style="color:#98C379;"> iodef</span><span style="color:#98C379;"> &quot;mailto:security@example.com&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 允许多个 CA</span></span>
<span class="line"><span style="color:#61AFEF;">example.com.</span><span style="color:#98C379;"> IN</span><span style="color:#98C379;"> CAA</span><span style="color:#D19A66;"> 0</span><span style="color:#98C379;"> issue</span><span style="color:#98C379;"> &quot;letsencrypt.org&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">example.com.</span><span style="color:#98C379;"> IN</span><span style="color:#98C379;"> CAA</span><span style="color:#D19A66;"> 0</span><span style="color:#98C379;"> issue</span><span style="color:#98C379;"> &quot;digicert.com&quot;</span></span>
<span class="line"><span style="color:#61AFEF;">example.com.</span><span style="color:#98C379;"> IN</span><span style="color:#98C379;"> CAA</span><span style="color:#D19A66;"> 0</span><span style="color:#98C379;"> issuewild</span><span style="color:#98C379;"> &quot;;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 禁止所有 CA 签发证书</span></span>
<span class="line"><span style="color:#61AFEF;">example.com.</span><span style="color:#98C379;"> IN</span><span style="color:#98C379;"> CAA</span><span style="color:#D19A66;"> 0</span><span style="color:#98C379;"> issue</span><span style="color:#98C379;"> &quot;;&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">CAA 的安全意义</p><ul><li>防止未授权 CA 为域名签发证书</li><li>即使攻击者控制了 DNS，也无法从未授权的 CA 获取证书</li><li>CA 在签发证书前必须检查 CAA 记录</li><li>自 2017 年 9 月起，所有 CA 必须遵守 CAA 记录</li></ul></div><h3 id="证书透明度-certificate-transparency" tabindex="-1"><a class="header-anchor" href="#证书透明度-certificate-transparency"><span>证书透明度（Certificate Transparency）</span></a></h3><p>CT 要求 CA 将签发的所有证书记录到公开的、可审计的日志中：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>CT 工作原理：</span></span>
<span class="line"><span>1. CA 签发证书前，将预证书提交到 CT Log</span></span>
<span class="line"><span>2. CT Log 返回 SCT（Signed Certificate Timestamp）</span></span>
<span class="line"><span>3. CA 将 SCT 嵌入证书或通过 OCSP/TLS 扩展提供</span></span>
<span class="line"><span>4. 域名所有者可以监控 CT Log，发现未授权证书</span></span>
<span class="line"><span></span></span>
<span class="line"><span>CT 的安全价值：</span></span>
<span class="line"><span>- 快速发现未授权/恶意签发的证书</span></span>
<span class="line"><span>- 提供证书签发的公开审计追踪</span></span>
<span class="line"><span>- 域名所有者可以设置监控告警</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="ct-监控工具" tabindex="-1"><a class="header-anchor" href="#ct-监控工具"><span>CT 监控工具</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 crt.sh 查询域名的所有证书</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://crt.sh/?q=example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 Google CT Log 搜索</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://transparencyreport.google.com/https/certificates</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 使用 certspotter 监控 CT Log</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://github.com/SSLMate/certspotter</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 命令行查询</span></span>
<span class="line"><span style="color:#61AFEF;">curl</span><span style="color:#D19A66;"> -s</span><span style="color:#98C379;"> &quot;https://crt.sh/?q=example.com&amp;output=json&quot;</span><span style="color:#ABB2BF;"> | </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">  jq</span><span style="color:#98C379;"> &#39;.[].name_value&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">sort</span><span style="color:#D19A66;"> -u</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="nginx-中启用-ct" tabindex="-1"><a class="header-anchor" href="#nginx-中启用-ct"><span>Nginx 中启用 CT</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># OpenSSL 1.1.0+ 支持 CT</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 需要编译时启用 --with-openssl-opt=enable-ct</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">    server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate </span><span style="color:#ABB2BF;">    /etc/nginx/ssl/example.com-fullchain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 启用 CT（需要证书包含 SCT）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ssl_ct on;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 指定 CT Log 列表</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ssl_ct_log /etc/nginx/ct/logs.json;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container warning"><p class="hint-container-title">CT 配置注意事项</p><ul><li>Let&#39;s Encrypt 证书自动包含 SCT</li><li>其他 CA 的证书可能需要手动添加 SCT</li><li>ssl_ct 指令需要 Nginx 编译时包含 CT 支持</li><li>大多数情况下不需要手动配置 CT，CA 已自动处理</li></ul></div><hr><h2 id="安全配置验证工具" tabindex="-1"><a class="header-anchor" href="#安全配置验证工具"><span>安全配置验证工具</span></a></h2><h3 id="ssl-labs-server-test" tabindex="-1"><a class="header-anchor" href="#ssl-labs-server-test"><span>SSL Labs Server Test</span></a></h3><p>最权威的在线 HTTPS 安全检测工具：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>使用方式：</span></span>
<span class="line"><span>1. 访问 https://www.ssllabs.com/ssltest/</span></span>
<span class="line"><span>2. 输入域名</span></span>
<span class="line"><span>3. 等待测试完成（通常 1-3 分钟）</span></span>
<span class="line"><span>4. 查看评级和详细报告</span></span>
<span class="line"><span></span></span>
<span class="line"><span>测试项目：</span></span>
<span class="line"><span>- 证书验证</span></span>
<span class="line"><span>- 协议支持</span></span>
<span class="line"><span>- 密码套件强度</span></span>
<span class="line"><span>- 前向保密支持</span></span>
<span class="line"><span>- HSTS 配置</span></span>
<span class="line"><span>- OCSP Stapling</span></span>
<span class="line"><span>- 已知漏洞检测</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="testssl-sh" tabindex="-1"><a class="header-anchor" href="#testssl-sh"><span><a href="http://testssl.sh" target="_blank" rel="noopener noreferrer">testssl.sh</a></span></a></h3><p>功能最全面的命令行 SSL 测试工具：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 安装</span></span>
<span class="line"><span style="color:#61AFEF;">git</span><span style="color:#98C379;"> clone</span><span style="color:#D19A66;"> --depth</span><span style="color:#D19A66;"> 1</span><span style="color:#98C379;"> https://github.com/drwetter/testssl.sh.git</span></span>
<span class="line"><span style="color:#56B6C2;">cd</span><span style="color:#98C379;"> testssl.sh</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 完整测试</span></span>
<span class="line"><span style="color:#61AFEF;">./testssl.sh</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 仅测试协议</span></span>
<span class="line"><span style="color:#61AFEF;">./testssl.sh</span><span style="color:#D19A66;"> -P</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 仅测试密码套件</span></span>
<span class="line"><span style="color:#61AFEF;">./testssl.sh</span><span style="color:#D19A66;"> -E</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 仅测试漏洞</span></span>
<span class="line"><span style="color:#61AFEF;">./testssl.sh</span><span style="color:#D19A66;"> -U</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 仅测试 HTTP 头部</span></span>
<span class="line"><span style="color:#61AFEF;">./testssl.sh</span><span style="color:#D19A66;"> -H</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出 JSON 报告</span></span>
<span class="line"><span style="color:#61AFEF;">./testssl.sh</span><span style="color:#D19A66;"> --json</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 输出 HTML 报告</span></span>
<span class="line"><span style="color:#61AFEF;">./testssl.sh</span><span style="color:#D19A66;"> --html</span><span style="color:#98C379;"> example.com</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="openssl-命令行检测" tabindex="-1"><a class="header-anchor" href="#openssl-命令行检测"><span>openssl 命令行检测</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 检查证书信息</span></span>
<span class="line"><span style="color:#56B6C2;">echo</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> | </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">  openssl</span><span style="color:#98C379;"> x509</span><span style="color:#D19A66;"> -noout</span><span style="color:#D19A66;"> -text</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查协议支持</span></span>
<span class="line"><span style="color:#C678DD;">for</span><span style="color:#E06C75;"> proto</span><span style="color:#C678DD;"> in</span><span style="color:#98C379;"> ssl3</span><span style="color:#98C379;"> tls1</span><span style="color:#98C379;"> tls1_1</span><span style="color:#98C379;"> tls1_2</span><span style="color:#98C379;"> tls1_3</span><span style="color:#ABB2BF;">; </span><span style="color:#C678DD;">do</span></span>
<span class="line"><span style="color:#56B6C2;">  echo</span><span style="color:#D19A66;"> -n</span><span style="color:#98C379;"> &quot;</span><span style="color:#E06C75;">$proto</span><span style="color:#98C379;">: &quot;</span></span>
<span class="line"><span style="color:#61AFEF;">  openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -</span><span style="color:#E06C75;">$proto</span><span style="color:#ABB2BF;"> 2&gt;&amp;1 | </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">    grep</span><span style="color:#D19A66;"> -c</span><span style="color:#98C379;"> &quot;Protocol.*</span><span style="color:#E06C75;">$proto</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;"> || </span><span style="color:#56B6C2;">echo</span><span style="color:#98C379;"> &quot;not supported&quot;</span></span>
<span class="line"><span style="color:#C678DD;">done</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查 OCSP Stapling</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -status</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> | </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">  grep</span><span style="color:#98C379;"> &quot;OCSP response&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查证书链</span></span>
<span class="line"><span style="color:#61AFEF;">openssl</span><span style="color:#98C379;"> s_client</span><span style="color:#D19A66;"> -connect</span><span style="color:#98C379;"> example.com:443</span><span style="color:#D19A66;"> -showcerts</span><span style="color:#ABB2BF;"> 2&gt;</span><span style="color:#98C379;">/dev/null</span><span style="color:#ABB2BF;"> | </span><span style="color:#56B6C2;">\\</span></span>
<span class="line"><span style="color:#61AFEF;">  awk</span><span style="color:#98C379;"> &#39;/BEGIN CERT/,/END CERT/&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查 HSTS</span></span>
<span class="line"><span style="color:#61AFEF;">curl</span><span style="color:#D19A66;"> -sI</span><span style="color:#98C379;"> https://example.com</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -i</span><span style="color:#98C379;"> strict-transport</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检查所有安全头</span></span>
<span class="line"><span style="color:#61AFEF;">curl</span><span style="color:#D19A66;"> -sI</span><span style="color:#98C379;"> https://example.com</span><span style="color:#ABB2BF;"> | </span><span style="color:#61AFEF;">grep</span><span style="color:#D19A66;"> -iE</span><span style="color:#56B6C2;"> \\</span></span>
<span class="line"><span style="color:#98C379;">  &quot;strict-transport|x-frame|x-content-type|x-xss|referrer-policy|content-security&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="nmap-ssl-扫描" tabindex="-1"><a class="header-anchor" href="#nmap-ssl-扫描"><span>nmap SSL 扫描</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># 扫描 SSL 配置</span></span>
<span class="line"><span style="color:#61AFEF;">nmap</span><span style="color:#D19A66;"> --script</span><span style="color:#98C379;"> ssl-enum-ciphers</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 扫描证书信息</span></span>
<span class="line"><span style="color:#61AFEF;">nmap</span><span style="color:#D19A66;"> --script</span><span style="color:#98C379;"> ssl-cert</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 检测已知漏洞</span></span>
<span class="line"><span style="color:#61AFEF;">nmap</span><span style="color:#D19A66;"> --script</span><span style="color:#98C379;"> ssl-heartbleed</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"><span style="color:#61AFEF;">nmap</span><span style="color:#D19A66;"> --script</span><span style="color:#98C379;"> ssl-poodle</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> example.com</span></span>
<span class="line"><span style="color:#61AFEF;">nmap</span><span style="color:#D19A66;"> --script</span><span style="color:#98C379;"> ssl-ccs-injection</span><span style="color:#D19A66;"> -p</span><span style="color:#D19A66;"> 443</span><span style="color:#98C379;"> example.com</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="在线检测工具汇总" tabindex="-1"><a class="header-anchor" href="#在线检测工具汇总"><span>在线检测工具汇总</span></a></h3><table><thead><tr><th>工具</th><th>网址</th><th>用途</th></tr></thead><tbody><tr><td>SSL Labs</td><td><a href="http://ssllabs.com/ssltest" target="_blank" rel="noopener noreferrer">ssllabs.com/ssltest</a></td><td>HTTPS 安全评级</td></tr><tr><td>Mozilla Observatory</td><td><a href="http://observatory.mozilla.org" target="_blank" rel="noopener noreferrer">observatory.mozilla.org</a></td><td>综合安全检测</td></tr><tr><td>Security Headers</td><td><a href="http://securityheaders.com" target="_blank" rel="noopener noreferrer">securityheaders.com</a></td><td>安全响应头检测</td></tr><tr><td>CSP Evaluator</td><td><a href="http://csp-evaluator.withgoogle.com" target="_blank" rel="noopener noreferrer">csp-evaluator.withgoogle.com</a></td><td>CSP 策略分析</td></tr><tr><td>HSTS Preload</td><td><a href="http://hstspreload.org" target="_blank" rel="noopener noreferrer">hstspreload.org</a></td><td>HSTS Preload 检测/申请</td></tr><tr><td><a href="http://crt.sh" target="_blank" rel="noopener noreferrer">crt.sh</a></td><td><a href="http://crt.sh" target="_blank" rel="noopener noreferrer">crt.sh</a></td><td>CT Log 证书搜索</td></tr></tbody></table><hr><h2 id="完整安全加固配置" tabindex="-1"><a class="header-anchor" href="#完整安全加固配置"><span>完整安全加固配置</span></a></h2><h3 id="生产级配置" tabindex="-1"><a class="header-anchor" href="#生产级配置"><span>生产级配置</span></a></h3><div class="language-nginx line-numbers-mode" data-highlighter="shiki" data-ext="nginx" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-nginx"><span class="line"><span style="color:#7F848E;font-style:italic;"># 参考：</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://nginx.org/en/docs/http/ngx_http_ssl_module.html</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># https://ssl-config.mozilla.org/</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ===== 全局 SSL 配置 =====</span></span>
<span class="line"><span style="color:#C678DD;">http</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 全局协议版本</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_protocols </span><span style="color:#ABB2BF;">TLSv1.2 TLSv1.3;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 全局密码套件</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_ciphers </span><span style="color:#98C379;">&#39;ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384:DHE-RSA-CHACHA20-POLY1305&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_prefer_server_ciphers </span><span style="color:#D19A66;">off</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 全局 ECDHE 曲线</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_ecdh_curve </span><span style="color:#ABB2BF;">X25519:secp256r1:secp384r1;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # 全局 Session 配置</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_cache </span><span style="color:#ABB2BF;">shared:SSL:10m;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_timeout </span><span style="color:#D19A66;">1d</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_session_tickets </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # DH 参数</span></span>
<span class="line"><span style="color:#C678DD;">    ssl_dhparam </span><span style="color:#ABB2BF;">/etc/nginx/ssl/dhparam.pem;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== HTTPS 服务器 =====</span></span>
<span class="line"><span style="color:#C678DD;">    server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">        listen </span><span style="color:#D19A66;">443</span><span style="color:#ABB2BF;"> ssl;</span></span>
<span class="line"><span style="color:#C678DD;">        listen </span><span style="color:#ABB2BF;">[::]:443 ssl;</span></span>
<span class="line"><span style="color:#C678DD;">        http2 </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">        ssl_certificate </span><span style="color:#ABB2BF;">    /etc/nginx/ssl/example.com-fullchain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">        ssl_certificate_key </span><span style="color:#ABB2BF;">/etc/nginx/ssl/example.com.key;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # OCSP Stapling</span></span>
<span class="line"><span style="color:#C678DD;">        ssl_stapling </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        ssl_stapling_verify </span><span style="color:#D19A66;">on</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        ssl_trusted_certificate </span><span style="color:#ABB2BF;">/etc/nginx/ssl/chain.pem;</span></span>
<span class="line"><span style="color:#C678DD;">        resolver </span><span style="color:#D19A66;">8.8.8.8</span><span style="color:#D19A66;"> 8.8.4.4</span><span style="color:#ABB2BF;"> valid=300s;</span></span>
<span class="line"><span style="color:#C678DD;">        resolver_timeout </span><span style="color:#D19A66;">5s</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # 性能优化</span></span>
<span class="line"><span style="color:#C678DD;">        ssl_buffer_size </span><span style="color:#D19A66;">4k</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # ===== 安全响应头 =====</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # HSTS</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Strict-Transport-Security </span><span style="color:#98C379;">&quot;max-age=63072000; includeSubDomains; preload&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # CSP</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Content-Security-Policy </span><span style="color:#98C379;">&quot;default-src &#39;self&#39;; script-src &#39;self&#39;; style-src &#39;self&#39; &#39;unsafe-inline&#39;; img-src &#39;self&#39; data: https:; font-src &#39;self&#39; https://fonts.gstatic.com; connect-src &#39;self&#39;; frame-ancestors &#39;none&#39;; base-uri &#39;self&#39;; form-action &#39;self&#39;; upgrade-insecure-requests&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # 点击劫持防护</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">X-Frame-Options </span><span style="color:#98C379;">&quot;DENY&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # MIME 嗅探防护</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">X-Content-Type-Options </span><span style="color:#98C379;">&quot;nosniff&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # XSS 防护</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">X-XSS-Protection </span><span style="color:#98C379;">&quot;0&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # Referer 策略</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Referrer-Policy </span><span style="color:#98C379;">&quot;strict-origin-when-cross-origin&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        # 权限策略</span></span>
<span class="line"><span style="color:#C678DD;">        add_header </span><span style="color:#ABB2BF;">Permissions-Policy </span><span style="color:#98C379;">&quot;camera=(), microphone=(), geolocation=()&quot;</span><span style="color:#ABB2BF;"> always;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">        location</span><span style="color:#ABB2BF;"> / {</span></span>
<span class="line"><span style="color:#C678DD;">            root </span><span style="color:#ABB2BF;">/var/www/html;</span></span>
<span class="line"><span style="color:#ABB2BF;">        }</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    # ===== HTTP 重定向 =====</span></span>
<span class="line"><span style="color:#C678DD;">    server</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">        listen </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">        listen </span><span style="color:#ABB2BF;">[::]:80;</span></span>
<span class="line"><span style="color:#C678DD;">        server_name </span><span style="color:#ABB2BF;">example.com;</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#D19A66;"> 301</span><span style="color:#ABB2BF;"> https://$</span><span style="color:#E06C75;">host</span><span style="color:#ABB2BF;">$</span><span style="color:#E06C75;">request_uri</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="常见安全漏洞与修复" tabindex="-1"><a class="header-anchor" href="#常见安全漏洞与修复"><span>常见安全漏洞与修复</span></a></h2><h3 id="poodle-padding-oracle-on-downgraded-legacy-encryption" tabindex="-1"><a class="header-anchor" href="#poodle-padding-oracle-on-downgraded-legacy-encryption"><span>POODLE（Padding Oracle On Downgraded Legacy Encryption）</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>影响：SSLv3</span></span>
<span class="line"><span>修复：禁用 SSLv3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ssl_protocols TLSv1.2 TLSv1.3;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="beast-browser-exploit-against-ssl-tls" tabindex="-1"><a class="header-anchor" href="#beast-browser-exploit-against-ssl-tls"><span>BEAST（Browser Exploit Against SSL/TLS）</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>影响：TLS 1.0 + CBC 模式</span></span>
<span class="line"><span>修复：禁用 TLS 1.0，使用 AEAD 密码套件</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ssl_protocols TLSv1.2 TLSv1.3;</span></span>
<span class="line"><span>ssl_ciphers &#39;ECDHE+AESGCM:ECDHE+CHACHA20:DHE+AESGCM:DHE+CHACHA20&#39;;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="heartbleed" tabindex="-1"><a class="header-anchor" href="#heartbleed"><span>Heartbleed</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>影响：OpenSSL 1.0.1 - 1.0.1f</span></span>
<span class="line"><span>修复：升级 OpenSSL 到 1.0.1g+，重新生成密钥和证书</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 检测</span></span>
<span class="line"><span>nmap --script ssl-heartbleed -p 443 example.com</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="lucky13" tabindex="-1"><a class="header-anchor" href="#lucky13"><span>Lucky13</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>影响：TLS 使用 CBC 模式时</span></span>
<span class="line"><span>修复：使用 AEAD 密码套件替代 CBC</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ssl_ciphers &#39;ECDHE+AESGCM:ECDHE+CHACHA20&#39;;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="robot-return-of-bleichenbacher-s-oracle-threat" tabindex="-1"><a class="header-anchor" href="#robot-return-of-bleichenbacher-s-oracle-threat"><span>ROBOT（Return Of Bleichenbacher&#39;s Oracle Threat）</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>影响：RSA PKCS#1 v1.5 密钥交换</span></span>
<span class="line"><span>修复：禁用 RSA 密钥交换，使用 ECDHE</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ssl_ciphers &#39;ECDHE+AESGCM:ECDHE+CHACHA20:DHE+AESGCM&#39;;</span></span>
<span class="line"><span># 确保不包含 RSA 密钥交换的套件</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="logjam" tabindex="-1"><a class="header-anchor" href="#logjam"><span>Logjam</span></a></h3><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>影响：DHE 密钥交换使用 1024 bit 或更弱的 DH 参数</span></span>
<span class="line"><span>修复：使用 2048+ bit DH 参数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ssl_dhparam /etc/nginx/ssl/dhparam.pem;  # 2048+ bit</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="延伸阅读" tabindex="-1"><a class="header-anchor" href="#延伸阅读"><span>延伸阅读</span></a></h2><ul><li><a href="https://nginx.org/en/docs/http/ngx_http_ssl_module.html" target="_blank" rel="noopener noreferrer">Nginx SSL Module 官方文档</a></li><li><a href="https://ssl-config.mozilla.org/" target="_blank" rel="noopener noreferrer">Mozilla SSL Configuration Generator</a></li><li><a href="https://owasp.org/www-project-secure-headers/" target="_blank" rel="noopener noreferrer">OWASP Secure Headers Project</a></li><li><a href="https://tools.ietf.org/html/rfc6797" target="_blank" rel="noopener noreferrer">RFC 6797 - HSTS</a></li><li><a href="https://www.w3.org/TR/CSP3/" target="_blank" rel="noopener noreferrer">W3C CSP Level 3</a></li><li><a href="https://tools.ietf.org/html/rfc6844" target="_blank" rel="noopener noreferrer">RFC 6844 - CAA</a></li><li><a href="https://tools.ietf.org/html/rfc6962" target="_blank" rel="noopener noreferrer">RFC 6962 - Certificate Transparency</a></li><li><a href="https://www.ssllabs.com/ssltest/" target="_blank" rel="noopener noreferrer">SSL Labs Server Test</a></li></ul>`,85)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};